Policy:
{
  "Version" : "2012-10-17",
  "Statement" : [ {
    "Sid" : "Enable IAM User Permissions",
    "Effect" : "Allow",
    "Principal" : {
      "AWS" : "arn:aws:iam::442426852386:root"
    },
    "Action" : "kms:*",
    "Resource" : "*"
  }, {
    "Sid" : "Allow use of the key by API",
    "Effect" : "Allow",
    "Principal" : {
      "AWS" : "arn:aws:iam::442426852386:role/plaidaws-ApiFunctionRole-3AgydT8vK0Fu"
    },
    "Action" : [ "kms:DescribeKey", "kms:Encrypt", "kms:GenerateDataKey*", "kms:ReEncrypt*" ],
    "Resource" : "*"
  }, {
    "Sid" : "Allow use of the key by processor",
    "Effect" : "Allow",
    "Principal" : {
      "AWS" : "arn:aws:iam::442426852386:role/plaidaws-WebhookProcessorFunctionRole-AxjZOhEGStqO"
    },
    "Action" : [ "kms:Decrypt", "kms:DescribeKey" ],
    "Resource" : "*"
  } ]
}
